"use client"

import animation from "react-useanimations/lib/volume"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Volume" from https://useanimations.com (MIT): https://useanimations.com/icons/volume
export function AnimatedVolume(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-toggle"
      {...props}
    />
  )
}
